file.content:
"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes the intent; the behaviour below matches
what the engine actually did, quirks included:

* `.packignore` files are UTF-8; lines are split like `str.splitlines()` and
  stripped of surrounding whitespace. `;` starts a comment line (`#` does
  not). Backslashes and brackets are ordinary characters; only `*`, `?` and
  `**` are special.
* A pattern is checked against every level of a file's path (each ancestor
  directory, then the file itself). The deepest level that any pattern
  matches decides. At one level, the deepest `.packignore` with a matching
  pattern decides, and within one `.packignore` a matching `!pattern` beats
  a matching exclusion, regardless of order.
* A `.packignore` inside an excluded directory is not read.
* Executable files (any execute bit) and files whose first line contains
  `@generated` are excluded, unless a `!pattern` matches the file itself.
* The engine stored the tree on a case-insensitive, normalization-insensitive
  filesystem: paths that differ only in case or Unicode normalization are one
  file, named after the first one seen but with the last one's contents.
"""

import os
import re
import stat
import unicodedata

IGNORE_FILE = ".packignore"


class PackignoreError(Exception):
    """The tree can't be evaluated (packignore reported an internal error)."""


def _fold(name):
    return unicodedata.normalize("NFD", unicodedata.normalize("NFD", name).casefold())


class _Node:
    __slots__ = ("name", "children", "is_dir", "path")

    def __init__(self, name, is_dir, path):
        self.name = name
        self.is_dir = is_dir
        self.path = path  # real path of the (last) source file, for files
        self.children = {} if is_dir else None


def _build_tree(root):
    """Mirror how the engine stored the uploaded tree."""
    top = _Node("", True, None)
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            parts = os.path.relpath(full, root).replace(os.sep, "/").split("/")
            node = top
            for part in parts[:-1]:
                key = _fold(part)
                child = node.children.get(key)
                if child is None:
                    child = node.children[key] = _Node(part, True, None)
                elif not child.is_dir:
                    raise PackignoreError("internal error")
                node = child
            key = _fold(parts[-1])
            child = node.children.get(key)
            if child is None:
                node.children[key] = _Node(parts[-1], False, full)
            elif child.is_dir:
                raise PackignoreError("internal error")
            else:
                child.path = full
    return top


def _is_globstar(seg):
    return seg == "**"


def _translate(pat):
    """Translate a glob (no leading or trailing "/") into a regex string."""
    segs = []
    for seg in pat.split("/"):
        if not (_is_globstar(seg) and segs and _is_globstar(segs[-1])):
            segs.append(seg)
    if segs == ["**"]:
        return ".*"
    out = []
    for i, seg in enumerate(segs):
        if _is_globstar(seg):
            out.append("(?:.*/)?" if i == 0 else "(?:/.*)?")
            continue
        if i > 0 and not (i == 1 and _is_globstar(segs[0])):
            out.append("/")
        for ch in seg:
            if ch == "*":
                out.append("[^/]*")
            elif ch == "?":
                out.append("[^/]")
            else:
                out.append(re.escape(ch))
    return "".join(out)


def _expand_braces(pat):
    """Expand `{a,b}` groups: each runs from a `{` to the next `}`, with no
    nesting, and text produced by a group is never expanded again."""
    i = pat.find("{")
    j = pat.find("}", i + 1) if i >= 0 else -1
    if j < 0:
        return [pat]
    rest = _expand_braces(pat[j + 1:])
    return [pat[:i] + alt + tail for alt in pat[i + 1:j].split(",") for tail in rest]


def _specificity(pat):
    """How specific a pattern is: its literal characters, not counting `*`,
    `?`, `/`, any `}`, or the `{` and `,` of a brace group."""
    score = 0
    i = 0
    while i < len(pat):
        ch = pat[i]
        if ch == "{":
            j = pat.find("}", i + 1)
            if j >= 0:
                score += sum(c not in "*?/," for c in pat[i + 1:j])
                i = j + 1
                continue
        if ch not in "*?/}":
            score += 1
        i += 1
    return score


class _Pattern:
    __slots__ = ("negate", "dir_only", "anchored", "regex", "score")

    def __init__(self, line):
        self.negate = line.startswith("!")
        if self.negate:
            line = line[1:]
        self.score = _specificity(line)
        self.dir_only = line.endswith("/")
        line = line.rstrip("/")
        self.anchored = "/" in line
        stripped = line.lstrip("/")
        alts = dict.fromkeys(_translate(a) for a in _expand_braces(stripped) if a)
        self.regex = re.compile("|".join(alts), re.S) if alts else None

    def matches(self, rel, base, is_dir):
        if self.regex is None or (self.dir_only and not is_dir):
            return False
        return self.regex.fullmatch(rel if self.anchored else base) is not None


def _parse(data):
    text = data.decode("utf-8")
    pats = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        pats.append(_Pattern(line))
    return pats


def _decide(rules, rel, is_dir):
    """rules: list of (prefix, patterns), shallowest first. Return True
    (excluded), False (re-included) or None (no match)."""
    base = rel.rsplit("/", 1)[-1]
    for prefix, pats in reversed(rules):
        sub = rel[len(prefix):]
        best = None
        for p in pats:
            if p.matches(sub, base, is_dir) and (best is None or p.score >= best.score):
                best = p
        if best is not None:
            return not best.negate
    return None


def _builtin_excluded(path):
    st = os.stat(path)
    if stat.S_IMODE(st.st_mode) & 0o111:
        return True
    with open(path, "rb") as f:
        first = b""
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            i = chunk.find(b"\n")
            if i >= 0:
                first += chunk[:i]
                break
            first += chunk
            if b"@generated" in first[-65536 - 10:]:
                return True
    return b"@generated" in first


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    top = _build_tree(root)
    result = []

    def walk(node, prefix, rules, excluded):
        ign = None if excluded else node.children.get(_fold(IGNORE_FILE))
        if ign is not None and not ign.is_dir and ign.name == IGNORE_FILE:
            with open(ign.path, "rb") as f:
                pats = _parse(f.read())
            if pats:
                rules = rules + [(prefix, pats)]
        for child in node.children.values():
            rel = prefix + child.name
            if child.is_dir:
                d = _decide(rules, rel, True)
                walk(child, rel + "/", rules, excluded if d is None else d)
            else:
                d = _decide(rules, rel, False)
                if d is None:
                    d = excluded or _builtin_excluded(child.path)
                if d:
                    result.append(rel)

    walk(top, "", [], False)
    return sorted(result)

